<?php
declare(strict_types=1);
$configPath=dirname(__DIR__).'/config/config.php';$config=is_file($configPath)?require $configPath:require dirname(__DIR__).'/config/config.example.php';date_default_timezone_set($config['app']['timezone']??'Asia/Baku');
function h(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}
$slug=trim((string)($_GET['slug']??''));$article=null;$related=[];$error=false;
try{$d=$config['database'];$pdo=new PDO("mysql:host={$d['host']};dbname={$d['name']};charset={$d['charset']}",$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$s=$pdo->prepare("SELECT a.*,c.name category_name FROM articles a LEFT JOIN categories c ON c.id=a.category_id WHERE a.slug=? AND a.status='published' LIMIT 1");$s->execute([$slug]);$article=$s->fetch()?:null;
if($article){$visitor=hash('sha256',($_SERVER['REMOTE_ADDR']??'').($_SERVER['HTTP_USER_AGENT']??''));$v=$pdo->prepare('INSERT INTO article_views(article_id,visitor_hash) VALUES(?,?)');$v->execute([$article['id'],$visitor]);$pdo->prepare('UPDATE articles SET views=views+1 WHERE id=?')->execute([$article['id']]);$r=$pdo->prepare("SELECT title,slug,excerpt FROM articles WHERE status='published' AND id<>? ORDER BY published_at DESC LIMIT 3");$r->execute([$article['id']]);$related=$r->fetchAll();}
}catch(Throwable $e){$error=true;}
if(!$article){http_response_code(404);}
$title=$article['title']??'Məqalə tapılmadı';?><!doctype html><html lang="az"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102b4e"><title><?=h($title)?> — RashadFinance</title><?php if($article):?><meta name="description" content="<?=h(mb_substr(strip_tags((string)$article['excerpt']),0,155))?>"><link rel="canonical" href="<?=h(rtrim($config['app']['base_url']??'','/'))?>/article.php?slug=<?=rawurlencode($article['slug'])?>"><?php endif;?><link rel="stylesheet" href="assets/css/site.css"></head><body>
<header class="site-header"><a class="brand" href="index.php"><span class="brand-mark">R</span><span>RASHAD<span class="brand-light">FINANCE</span></span></a><nav><a href="index.php#about">Haqqımda</a><a href="index.php#services">Xidmətlər</a><a href="blog.php">Bloq</a><a href="index.php#contact">Əlaqə</a></nav><a class="header-cta" href="index.php#contact">Konsultasiya al ↗</a></header>
<main class="article-page"><?php if($article):?><a class="back-link" href="blog.php">← Bütün məqalələr</a><article class="article-detail"><div class="section-kicker"><?=h($article['category_name']??'RASHADFINANCE')?></div><h1><?=h($article['title'])?></h1><div class="article-detail-meta"><?=h($article['published_at']??'')?> · <?=number_format((int)$article['views']+1)?> baxış</div><?php if($article['cover_image']):?><img class="article-hero-image" src="<?=h($article['cover_image'])?>" alt="<?=h($article['title'])?>"><?php endif;?><p class="article-excerpt"><?=h($article['excerpt'])?></p><div class="article-body"><?=nl2br(h($article['body']))?></div><?php if($article['source_url']):?><p class="article-source">Mənbə: <a href="<?=h($article['source_url'])?>" target="_blank" rel="noopener noreferrer">Xarici mənbəyə keçid ↗</a></p><?php endif;?></article><?php if($related):?><section class="related-articles"><h2>Digər məqalələr</h2><div class="article-grid"><?php foreach($related as $r):?><article class="article-card"><h3><?=h($r['title'])?></h3><p><?=h($r['excerpt'])?></p><a class="arrow-link" href="article.php?slug=<?=rawurlencode($r['slug'])?>">Oxu ↗</a></article><?php endforeach;?></div></section><?php endif;?><?php else:?><section class="not-found"><div class="section-kicker">404 / NOT FOUND</div><h1><?= $error?'Məlumat bazası bağlantısı yoxdur.':'Məqalə tapılmadı.' ?></h1><p>Linki yoxlayın və ya bloqa qayıdın.</p><a class="btn btn-primary" href="blog.php">Bloqa qayıt ↗</a></section><?php endif;?></main><footer><a class="brand footer-brand" href="index.php"><span class="brand-mark">R</span><span>RASHAD<span class="brand-light">FINANCE</span></span></a><span>© <?=date('Y')?> RashadFinance</span><a href="admin/">Admin panel ↗</a></footer></body></html>